"""Public accepted-workflow context and initialization, separate from real RPI returns."""
from __future__ import annotations

import copy
import hashlib
from pathlib import Path

PROFILE = "accepted-rpi-computational-v1"


def accepted_panel():
    """Human-agreed first panel, with explicitly conditional geometry and masses."""
    specimens, preparations = [], []
    for temperature in (750, 800, 850):
        prep = f"conditional-prep-{temperature}"
        preparations.append({"preparation_id": prep, "lot_id": "Ames-conditional-lot-unconfirmed",
            "conditions": {"method": "sealed_quartz_degassing", "temperature_c": 600.,
                           "hold_time_s": 900., "heating_rate_c_min": 5.,
                           "cooling_mode": "furnace_cooling", "group_mass_g": 5.},
            "status": "accepted_plan_executed_only_in_conditional_branch"})
        for repeat in range(1, 4):
            sid = f"panel-{temperature}-{repeat}"
            specimens.append({"specimen_id": sid, "preparation_id": prep, "cycle_id": "sps-"+sid,
                "conditions": {"route": "ames_ndfeb_sps_conditional", "temperature_c": temperature,
                    "pressure_mpa": 60., "heating_rate_c_min": 10., "hold_time_s": 300.,
                    "mass_g": 5./3, "diameter_mm": 10., "post_treatment": "none",
                    "process_stage": "initial_sps", "cooling_mode": "furnace_cooling",
                    "geometry_status": "10mm_assumed_for_displacement_sensitivity_not_RPI_fact",
                    "mass_status": "equal_split_of_planned_5g_group_not_measured_mass"},
                "measurements": ["density_g_cm3", "sps_log"]})
    return {"origin": "synthetic", "lot_id": "Ames-conditional-lot-unconfirmed",
            "operation": "manufacture", "output_stage": "as_sintered",
            "preparations": preparations, "specimens": specimens,
            "design_origin": "human_agreed_RPI_panel_not_agent_selection",
            "evidence_status": "conditional_computational_branch_not_physical_request"}


def source_packet(repo, *, additional_sources=None):
    """Bind real literature and methods without exposing simulator configuration."""
    from .models import public_source_packet
    repo = Path(repo)
    packet = public_source_packet()
    accepted_path = repo / "artifacts/rpi/accepted-workflow-20260916/PUBLIC_CAMPAIGN_CONTEXT.md"
    accepted = accepted_path.read_bytes()
    packet["accepted_workflow"] = {"text": accepted.decode(),
        "sha256": hashlib.sha256(accepted).hexdigest(), "origin": "reconciled_human_agreement"}
    packet["task"] = {
        "profile": PROFILE,
        "material_question": "How can the available Ames powder and processing route produce dense material while controlling microstructure and processing burden, and what evidence improves the next processing decision?",
        "lower_temperature": "starting hypothesis, not predetermined optimum",
        "starting_panel": accepted_panel(),
        "starting_panel_origin": "human_agreed; preserve temperature,pressure,ramp,dwell and shared preparations",
        "execution_status": "Conditional virtual investigation; no RPI measurements have returned",
        "available_resources": {"synthetic_manufacturing_slots": 24,
            "policy_spend_limit_usd_per_episode": 1., "physical_execution": False},
        "mission": "Build and use source-informed executable models, commit conditional predictions, inspect returned measurements, explore competing explanations and decisions, and produce a defensible subsequent experiment or information request. Challenge applicability; distinguish model disagreement, parameter ranges, measurement error and specimen scatter. Record what would change the next decision. You decide investigations and when evidence is sufficient.",
        "semantics": {
            "manufacture": "submit_batch request.operation=manufacture (default); new specimen IDs reserve manufacturing slots. Accepted panel bodies share one preparation per temperature and separate SPS cycles.",
            "measure": "submit_batch request.operation=measure; existing specimen IDs and original preparation/cycle IDs; input_stage=output_stage=current released stage. No new manufacturing slots. Include prior_processing_conditions copied from released operation history on each specimen, and remaining_mass_g or conditions.mass_g. conditions may specify measurement_context. Measurements are repeatable unless material was consumed.",
            "anneal": "submit_batch request.operation=anneal; existing IDs; input_stage=current released stage, output_stage=after_second_anneal; conditions.operation=anneal, output_stage=after_second_anneal, cooling_mode=argon_quench OR furnace_cooling as an explicit computational branch, mass_g; prior_processing_conditions is the ordered actual processing history. The combined 900C/2h then 520C/2h sequence has no assumed intermediate measurement. Optional treatment_cycle_id records a separate anneal cycle. No new manufacturing slots.",
            "destructive": "Declare consumed_mass_g, destructive and specimen_available directly on each specimen, alongside specimen_id, when interpretation requires sectioning/consumption. These fields do not belong inside conditions or at request root. Released outcomes determine remaining inventory; request declarations alone do not establish consumption. Further full-body measurement requires remaining usable material.",
            "requests": "Operator fulfillment executes conditional native responses and separately reviews/releases them after you record wait. A source-domain or unsupported-operation failure is actionable feedback, not evidence of physical failure.",
        },
        "measurement_capabilities": ["density_g_cm3", "sps_log", "microstructure", "grain_size_nm",
            "grain_d90_nm", "coarse_number_fraction", "porosity_area_fraction", "boundary_chemistry", "powder_icp_oes"],
        "measurement_limits": "Raw Archimedes fixtures and constructed field features use existing reducers. Grain descriptors represent selected 2D fields; no actual SEM images. Chemistry may return explicit unavailable records. SPS displacement includes tooling response. Instrument error assumptions are computational sensitivities, not RPI calibration.",
        "scientific_freedom": "Use arbitrary isolated Python, source inspection, model staging/adoption, numerical counterfactual branches and evidence-driven requests. Work beyond the human initial panel is computational only and any physical follow-up remains proposed. No model edit or candidate nomination is required.",
        "final_record": "Use record_decision(stop, rationale) for a supported scientific conclusion, including conditional forecasts, model discrepancy/retention, discriminating measurements and a subsequent experiment/information request with prediction, comparator, specimen/stage, resource implications and independent confirmation. A wait with no further useful computation is explicit incomplete evidence; generic missing RPI data is not the investigation.",
    }
    if additional_sources:
        packet["literature_methods"] = copy.deepcopy(additional_sources)
    return packet


def investigator_interface(sources, instructions, tools):
    """Use the expanded objective only for a versioned accepted-workflow source packet."""
    dense_feedback = sources.get("task", {}).get("feedback_profile") == "dense-public-v1"
    tools = copy.deepcopy(tools)
    if not dense_feedback:
        tools = [tool for tool in tools
                 if tool["name"] not in {"preview_request", "inspect_feedback"}]
    if sources.get("task", {}).get("profile") != PROFILE:
        return instructions, tools
    instructions = instructions.replace(
        "The material question is whether lower-temperature SPS can maintain density while limiting\ngrain growth relative to the laboratory reference. The first reference/two-alternative panel\nis human-proposed, not your experimental design.",
        "Investigate how the available Ames powder and accepted processing route can produce dense material while controlling microstructure and processing burden. Lower SPS temperature is a starting hypothesis, not a predetermined optimum. The accepted 750/800/850 C first panel is human-agreed; its choice is not your experimental design.")
    instructions = instructions.replace("Fit only compatible lot/origin/process/method/population/units; enforce both domain bounds.",
        "Fit source-compatible observations with explicit routes, stages, populations and units. Separately labeled cross-route conditional models and extrapolation hypotheses are allowed and useful; do not represent them as pooled source calibration or measured Ames behavior. Explore transfer uncertainty and competing models.")
    instructions += "\nThis is the versioned full computational investigation. Read task, accepted_workflow and literature_methods in the source packet. Existing specimens support measure and anneal requests through submit_batch; inspect task.semantics and released specimen_histories. Preserve actual stage and history. Native conditional returns are explicitly synthetic and may disagree with your source-informed model. Your model code and scientific conclusions are your own; you have no simulator internals. No selected temperature or conclusion is required.\n"
    instructions += "\nAnneal control contract: use conditions.anneal_steps, never conditions.steps. Each ordered step requires stage, temperature_c, hold_time_s and heating_rate_c_min; optional pressure_mpa must be zero and cooling_rate_c_min positive. An as_sintered to after_second_anneal request requires after_first_anneal then after_second_anneal steps. A request from after_first_anneal requires only after_second_anneal. Example syntax for the accepted sequence: anneal_steps=[{stage:'after_first_anneal',temperature_c:900,hold_time_s:7200,heating_rate_c_min:10},{stage:'after_second_anneal',temperature_c:520,hold_time_s:7200,heating_rate_c_min:10}]. Top-level temperature_c, hold_time_s, heating_rate_c_min and pressure_mpa, if supplied, must agree with the first step. With no anneal_steps, only the accepted default sequence is supported. cooling_mode is furnace_cooling or argon_quench. Use canonical steps for any proposed change of annealing controls; malformed controls are rejected. Read corrected released processing histories before reusing a specimen.\n"
    if dense_feedback:
        resources = sources.get("task", {}).get("available_resources", {})
        episode_usd = resources.get("policy_spend_limit_usd_per_episode", 5)
        study_usd = resources.get("study_additional_spend_limit_usd", 15)
        instructions += (
            "\nThis fresh untrained RPI-informed baseline includes rpi_historical_evidence and "
            "diagnostic_procedures in read_sources. Inspect the checked historical email/image "
            "transcriptions and paired published annealing observations before constructing "
            "your prior. Their provenance distinguishes historical Ames powder, other material "
            "routes, expert expectations and this campaign; historical/current lot equivalence "
            "and the particle-versus-grain interpretation of feedstock size remain unresolved. "
            "Expert expectations are contestable priors, not prescribed outcomes.\n"
            "Use preview_request to inspect the effective request and its predictions without "
            "committing specimens or executing an experiment. Select a nonempty measurements "
            "list explicitly; an omitted list defaults to density alone. Inspect_feedback and "
            "the released-evidence summaries expose deterministic public checks and raw references. "
            "They do not supply scientific conclusions. Preserve stage, method, population and "
            "uncertainty semantics; scenario ranges are not calibrated probability distributions.\n"
            f"The current episode has a cumulative USD {episode_usd:g} ceiling within a separate USD {study_usd:g} study. "
            "Inspect_state exposes current spending, full unresolved reservations and a closure "
            "reserve. Plan enough remaining inference to interpret each return and record your "
            "decision. Near the closure reserve, new experimental commitments become unavailable; "
            "reading, computation, scientific model revision and decision recording remain available "
            "within the full episode budget. Virtual exploration is separate from the approximately "
            "25 g physical plan and unknown real preparation/sectioning losses.\n"
            "Complete the scientific chain: prior model, committed prediction, chosen experiment, "
            "interpreted return, implemented revision or justified retention, and subsequent "
            "prediction and decision. You choose the investigation and stopping point. Before "
            "record_decision(stop), interpret every final relevant return and identify your supported "
            "conclusion, unresolved alternatives, executable model and evidence, next processing "
            "experiment/discriminating measurement/retained condition/justified withholding, "
            "conditional predictions, material implications and an appropriate confirmation step. "
            "A supported inconclusive decision is valid. A resource interruption or pending return "
            "does not complete the investigation. Do not manufacture certainty to finish.\n"
        )
    submit = next(t for t in tools if t["name"] == "submit_batch")
    submit["description"] = "Commit active-model predictions before proposing manufacture, measurement or anneal for operator review. Manufacture reserves fresh specimen slots. Existing-body operations reuse identity/history without new slots. Read task.semantics. No physical execution authority."
    schema = submit["parameters"]["properties"]["request"]
    schema["description"] = "Scientific operation request; manufacture creates new body reservations, measure/anneal refer to existing released bodies."
    schema["properties"].update(operation={"type": "string", "enum": ["manufacture", "measure", "anneal"]},
                                input_stage={"type": "string"}, output_stage={"type": "string"})
    schema["properties"]["specimens"]["items"]["properties"]["specimen_id"]["description"] = "Fresh identity for manufacture; existing identity for measure/anneal."
    if sources.get("task", {}).get("prompt_profile") == "enhanced-v1":
        from .investigator_prompt import ENHANCED_V1
        instructions = ENHANCED_V1
    return instructions, tools


def rpi_informed_source_packet(repo, *, historical_evidence, diagnostic_procedures,
                               additional_sources=None):
    """Compose reviewed public evidence into the fresh USD 5 baseline contract.

    This function accepts checked public source records only. It never reads a
    world configuration, owner calculation, protected evaluation or old policy
    conclusions. The legacy source builder and archived packets are unchanged.
    """
    if not isinstance(historical_evidence, dict) or not historical_evidence:
        raise ValueError("Checked historical RPI evidence is required")
    if not isinstance(diagnostic_procedures, (dict, list)) or not diagnostic_procedures:
        raise ValueError("Verified public diagnostic procedures are required")
    packet = source_packet(repo, additional_sources=additional_sources)
    packet["rpi_historical_evidence"] = copy.deepcopy(historical_evidence)
    packet["diagnostic_procedures"] = copy.deepcopy(diagnostic_procedures)
    task = packet["task"]
    task.update(
        baseline_id="rpi-informed-baseline-20260917",
        feedback_profile="dense-public-v1",
        anneal_model_domain="rpi-informed-v1",
        require_resource_status=True,
        execution_status=("Conditional virtual investigation with attributed historical RPI "
                          "evidence; no current-campaign physical returns are asserted"),
        physical_material_plan={
            "powder_stock_g": 25.0,
            "stock_basis": "approximate discussed stock, not verified usable mass",
            "actual_usable_stock_g": None,
            "losses_g": None,
            "confirmation_reserve_g": 10.0 / 3.0,
            "confirmation_basis": "planning allowance for two nominal bodies; adapt with justified allocation",
            "initial_panel_nominal_g": 15.0,
            "virtual_exploration_is_physical_allocation": False,
        },
    )
    task["available_resources"].update(
        policy_spend_limit_usd_per_episode=5.0,
        study_additional_spend_limit_usd=15.0,
        fresh_episode_count=3,
        historical_spending_reused=False,
        prior_unresolved_reservations_reused=False,
        inference_resource_status="inspect_state: live conservative accounting and closure reserve",
    )
    task["semantics"]["measurement_selection"] = (
        "Specify a nonempty measurements list at request or specimen level. Omission "
        "defaults to density alone; an explicit empty list is unsupported. Preview "
        "effective selections and forecasts before commitment."
    )
    task["conditional_anneal_domain"] = {
        "first_stage_maximum_temperature_c": 900.0,
        "second_stage_maximum_temperature_c": 600.0,
        "maximum_hold_time_s_per_step": 7200.0,
        "scope": "Shared numerical capability envelope of this conditional baseline, not a physical safety limit or calibrated validity claim",
        "outside_domain": "Preview rejects unsupported annealing controls before commitment; analysis and proposals outside the simulator remain possible",
        "qualitative_response": "Stage-local constructed boundary-contrast descriptions may be available for supported source-related histories; phase identities, kinetics and magnetic effects remain unresolved",
    }
    return packet


def initialize_computational(state, directory, *, campaign_id, sources):
    from .investigation.controller import Investigator
    from .operator import Campaign
    with Campaign.open(state, {"campaign_id": campaign_id, "execution_mode": "synthetic", "max_specimens": 24}) as campaign:
        if campaign.models() or campaign.state()["requests"]:
            raise ValueError("fresh computational initialization only; resume existing state")
        investigator = Investigator(campaign, directory, sources=sources)
        try:
            # No hidden-world or owner calculation is adopted as the agent's model.
            # The investigator builds its own model using the supplied literature.
            return {"status": "initialized_source_bound_no_inference", "campaign_id": campaign_id,
                    "source_packet_sha256": investigator.state()["source_packet_sha256"],
                    "physical_execution": False, "active_model_id": None}
        finally:
            investigator.close()
